package cli

import (
	"encoding/json"
	"errors"
	"fmt"
	"opnsense-cli/opnsense/api/system"
	"strconv"
	"strings"
)

// /system/gateway: System > Gateways > Configuration (api/routing/settings/*_gateway) and the gateway monitoring
// (api/routes/gateway/status). Items are selected by the # of print, the uuid or the gateway name. Gateways of
// dynamic interfaces (DHCP, PPPoE, ...) like WAN_DHCP are generated by OPNsense and not configured: their uuid is
// their name, changing one stores a configured override, removing the override brings back the generated gateway

const systemGatewayItemHelp = "the #, uuid or name of the gateway (like WAN_DHCP)"

const systemGatewayApplyHint = `Changes are only saved, run "/system/gateway apply" to apply them.`

// systemGatewayField maps a field argument to the API field of the gateway
type systemGatewayField struct {
	arg   string
	field string
}

// systemGatewayFieldMap lists the field arguments of add and set in the order of the GUI
var systemGatewayFieldMap = []systemGatewayField{
	{"disabled", "disabled"},
	{"description", "descr"},
	{"interface", "interface"},
	{"protocol", "ipprotocol"},
	{"address", "gateway"},
	{"upstream", "defaultgw"},
	{"far-gateway", "fargw"},
	{"priority", "priority"},
	{"weight", "weight"},
	{"monitor-disabled", "monitor_disable"},
	{"monitor", "monitor"},
	{"monitor-no-route", "monitor_noroute"},
	{"kill-states", "monitor_killstates"},
	{"kill-states-failback", "monitor_killstates_priority"},
	{"force-down", "force_down"},
	{"no-sync", "nosync"},
	{"latency-low", "latencylow"},
	{"latency-high", "latencyhigh"},
	{"loss-low", "losslow"},
	{"loss-high", "losshigh"},
	{"interval", "interval"},
	{"time-period", "time_period"},
	{"loss-interval", "loss_interval"},
	{"data-length", "data_length"},
}

// systemGatewayFieldArgs are the field arguments of add (with the OPNsense defaults) and set
func systemGatewayFieldArgs(add bool) []Arg {
	var defaultValue = func(value string) string {
		if add {
			return value
		}
		return ""
	}
	var threshold = func(name string, help string, min int, max int) Arg {
		return Arg{Name: name, Type: Int, Help: help + `, "" for the default`, Validate: ValidateRange(min, max)}
	}
	const unlimited = 1 << 30
	return []Arg{
		{Name: "interface", Help: "the interface the gateway is on, like lan or opt1", Required: add,
			Validate: systemGatewayValidateInterface, Complete: systemGatewayInterfaceKeys},
		{Name: "protocol", Help: "the address family", Values: []string{"ipv4", "ipv6"}, Default: defaultValue("ipv4")},
		{Name: "address", Help: `the IP address of the gateway, "" (or dynamic) for a dynamic interface`, Validate: systemGatewayValidateAddress},
		{Name: "description", Help: "any text", Validate: systemGatewayValidateText},
		{Name: "disabled", Type: Bool, Help: "keep the gateway, but don't use it", Default: defaultValue("no")},
		{Name: "upstream", Type: Bool, Help: "upstream gateway: a candidate for the default gateway", Default: defaultValue("no")},
		{Name: "far-gateway", Type: Bool, Help: "the gateway may be outside of the interface subnet", Default: defaultValue("no")},
		{Name: "priority", Type: Int, Help: "0-255, lower is more important when choosing the default gateway",
			Default: defaultValue("255"), Validate: ValidateRange(0, 255)},
		{Name: "weight", Type: Int, Help: "1-10, the weight in gateway groups", Default: defaultValue("1"), Validate: ValidateRange(1, 10)},
		{Name: "monitor-disabled", Type: Bool, Help: "no monitoring, the gateway is always considered up", Default: defaultValue("yes")},
		{Name: "monitor", Help: `the IP address to monitor (ping), "" for the gateway address`, Validate: ValidateIP},
		{Name: "monitor-no-route", Type: Bool, Help: "don't add a host route for the monitor address", Default: defaultValue("no")},
		{Name: "kill-states", Type: Bool, Help: "failover states: kill the states of the gateway when it goes down", Default: defaultValue("no")},
		{Name: "kill-states-failback", Type: Bool, Help: "failback states: kill the states of the gateway when a gateway with a higher priority comes up",
			Default: defaultValue("no")},
		{Name: "force-down", Type: Bool, Help: "consider the gateway down", Default: defaultValue("no")},
		{Name: "no-sync", Type: Bool, Help: "don't sync the gateway to an HA peer", Default: defaultValue("no")},
		threshold("latency-low", "latency low threshold in ms (default 200)", 1, unlimited),
		threshold("latency-high", "latency high threshold in ms (default 500)", 1, unlimited),
		threshold("loss-low", "packet loss low threshold in % (1-99, default 10)", 1, 99),
		threshold("loss-high", "packet loss high threshold in % (1-100, default 20)", 1, 100),
		threshold("interval", "probe interval in seconds (default 1)", 1, unlimited),
		threshold("time-period", "seconds the results are averaged over, at least 2*(interval+loss-interval) (default 60)", 1, unlimited),
		threshold("loss-interval", "seconds before a probe counts as lost (default 4)", 1, unlimited),
		threshold("data-length", "data bytes of a probe (default 1)", 0, unlimited),
	}
}

func init() {
	var menu = Root.Menu("system/gateway")
	menu.Help = "gateways and their monitoring (System > Gateways)"
	var item = Arg{Name: "item", Help: systemGatewayItemHelp, Positional: true, Required: true, Complete: systemGatewayItemNames}
	menu.Add(
		&Command{Name: "print", Help: "list the gateways with their status",
			Long: `FLAGS: default = the active default gateway now, upstream = a candidate for the default gateway,
dynamic = the address comes from a dynamic interface (DHCP, PPPoE, ...), generated = generated by OPNsense for a
dynamic interface and not configured (set stores an override), down = forced down.`,
			Args: []Arg{
				{Name: "detail", Help: "show all fields of every gateway", Type: Bool},
				{Name: "json", Help: "one JSON object per line, as the API returns them", Type: Bool},
				{Name: "search", Help: "only gateways where any field contains this text"},
			}, Run: systemGatewayPrint},
		&Command{Name: "show", Help: "show all fields of one gateway", Args: []Arg{item}, Run: systemGatewayShow},
		&Command{Name: "add", Help: "add a gateway, prints its uuid",
			Long: `name and interface are required, address is required on interfaces with a static address. If a
gateway with this name exists, add fails unless replace is given, then that gateway is replaced completely
(arguments not given are reset to their defaults, the name stays).

  add name=lan_gw interface=lan address=192.168.1.2 description="LAN router"
` + systemGatewayApplyHint,
			Args: append(append([]Arg{{Name: "name", Help: "1-32 characters of a-z, A-Z, 0-9, _ and -, can not be changed later",
				Required: true, Validate: systemGatewayValidateName}}, systemGatewayFieldArgs(true)...),
				Arg{Name: "replace", Help: "replace the gateway with the same name", Type: Bool}),
			Check: systemGatewayCheck, Run: systemGatewayAdd},
		&Command{Name: "set", Help: "change fields of a gateway, the others are kept",
			Long: `Setting a gateway generated for a dynamic interface (like WAN_DHCP) stores a configured override of it.
Gateways can not be renamed.
` + systemGatewayApplyHint,
			Args: append([]Arg{item, {Name: "name", Help: "can not be changed, OPNsense does not allow renaming a gateway",
				Validate: systemGatewayRefuseRename}}, systemGatewayFieldArgs(false)...),
			Check: systemGatewayCheck, Run: systemGatewaySet},
		&Command{Name: "remove", Help: "remove a configured gateway",
			Long: `Gateways in use by an interface, a gateway group or a static route can not be removed. Removing the
override of a gateway generated for a dynamic interface brings back the generated gateway, generated gateways
themselves can not be removed (disable them instead).
` + systemGatewayApplyHint,
			Args: []Arg{item}, Run: systemGatewayRemove},
		&Command{Name: "enable", Help: "enable a gateway", Long: systemGatewayApplyHint, Args: []Arg{item}, Run: systemGatewayEnabler(true)},
		&Command{Name: "disable", Help: "disable a gateway", Long: systemGatewayApplyHint, Args: []Arg{item}, Run: systemGatewayEnabler(false)},
		&Command{Name: "apply", Help: "apply the gateway changes: re-applies the routes and the default gateway",
			Long: `Re-applies the routing configuration like the Apply button of the GUI: the routes, the default
gateway and the gateway monitoring are reconfigured, routed traffic may be interrupted briefly.`,
			Run: systemGatewayApply},
		&Command{Name: "monitor", Help: "show loss, delay and status of the gateways every interval until Ctrl-C",
			Long: `Polls the gateway monitoring (dpinger): STATUS, packet LOSS, round trip time (DELAY) and its standard
deviation (STDDEV) per gateway, "~" when a gateway is not monitored. On a terminal the screen is redrawn,
otherwise a "--- time" line separates the refreshes. once prints the state once, json prints the raw API
objects, one per gateway and line.`,
			Args: []Arg{
				{Name: "once", Type: Bool, Help: "print the state once and stop"},
				{Name: "interval", Type: Duration, Default: "2s", Help: "pause between two refreshes", Validate: systemActivityValidateInterval},
				{Name: "json", Type: Bool, Help: "print the raw API objects as JSON, one per line"},
			},
			Run: systemGatewayMonitor},
	)
}

// --- validation

func systemGatewayValidateName(name string) error {
	if system.GatewayValidateName(name) != nil {
		return fmt.Errorf("must be 1-32 characters of a-z, A-Z, 0-9, _ and -, got %q", name)
	}
	return nil
}

func systemGatewayRefuseRename(string) error {
	return errors.New("can not be changed: OPNsense does not allow renaming a gateway, add a new gateway and remove this one")
}

func systemGatewayValidateAddress(value string) error {
	if value == system.GatewayDynamicAddress {
		return nil
	}
	if ValidateIP(value) != nil {
		return fmt.Errorf("must be an IPv4 or IPv6 address (or dynamic), got %q", value)
	}
	return nil
}

func systemGatewayValidateInterface(value string) error {
	if value == "" || strings.ContainsAny(value, " \t\r\n/") {
		return fmt.Errorf("must be an interface like lan or opt1, got %q", value)
	}
	return nil
}

func systemGatewayValidateText(value string) error {
	for _, char := range value {
		if char < 0x20 || char == 0x7f {
			return fmt.Errorf("must not contain control characters like newlines, got %q", value)
		}
	}
	return nil
}

// systemGatewayProtocol maps the protocol argument to the API value
func systemGatewayProtocol(value string) string {
	if strings.EqualFold(value, "ipv6") {
		return "inet6"
	}
	return "inet"
}

// systemGatewayProtocolName renders the API ipprotocol as protocol argument
func systemGatewayProtocolName(ipprotocol string) string {
	switch ipprotocol {
	case "inet":
		return "ipv4"
	case "inet6":
		return "ipv6"
	}
	return ipprotocol
}

// systemGatewayCheck checks the arguments which belong together
func systemGatewayCheck(args *Args) error {
	// add has the default protocol ipv4, set only checks a given protocol (the library checks against the gateway)
	if args.String("protocol") != "" && args.Has("address") {
		if err := system.GatewayValidateAddress(args.String("address"), systemGatewayProtocol(args.String("protocol")), true); err != nil {
			return fmt.Errorf("address %q does not match protocol=%s", args.String("address"), strings.ToLower(args.String("protocol")))
		}
	}
	if args.String("protocol") != "" && args.Has("monitor") {
		if err := system.GatewayValidateAddress(args.String("monitor"), systemGatewayProtocol(args.String("protocol")), false); err != nil {
			return fmt.Errorf("monitor %q does not match protocol=%s", args.String("monitor"), strings.ToLower(args.String("protocol")))
		}
	}
	for _, pair := range [][2]string{{"latency-low", "latency-high"}, {"loss-low", "loss-high"}} {
		if args.String(pair[0]) != "" && args.String(pair[1]) != "" && args.Int(pair[0]) >= args.Int(pair[1]) {
			return fmt.Errorf("%s must be lower than %s", pair[0], pair[1])
		}
	}
	return nil
}

// --- lookups

func systemGatewayApi(c *Context) (*system.SystemApi, error) {
	var opn, err = c.Api()
	if err != nil {
		return nil, err
	}
	return &system.SystemApi{OPNsense: opn}, nil
}

func systemGatewayUuid(gateway system.Gateway) string {
	return gateway.Uuid
}

func systemGatewayNames(gateway system.Gateway) []string {
	return []string{gateway.Name}
}

// systemGatewaySelect loads all gateways and finds the one selector refers to
func systemGatewaySelect(c *Context, api *system.SystemApi, selector string) (system.Gateway, error) {
	var gateways, err = api.GatewayList()
	if err != nil {
		return system.Gateway{}, err
	}
	return Select(c, selector, gateways, systemGatewayUuid, systemGatewayNames)
}

// systemGatewayItemNames completes item names from the API
func systemGatewayItemNames(c *Context) []string {
	var api, err = systemGatewayApi(c)
	if err != nil {
		return nil
	}
	var gateways, listErr = api.GatewayList()
	if listErr != nil {
		return nil
	}
	var names = make([]string, 0, len(gateways))
	for _, gateway := range gateways {
		names = append(names, gateway.Name)
	}
	return names
}

// systemGatewayInterfaceKeys completes interface= with the interfaces gateways can use
func systemGatewayInterfaceKeys(c *Context) []string {
	var api, err = systemGatewayApi(c)
	if err != nil {
		return nil
	}
	var interfaces, listErr = api.GatewayInterfaces()
	if listErr != nil {
		return nil
	}
	var keys = make([]string, 0, len(interfaces))
	for _, iface := range interfaces {
		keys = append(keys, iface.Key)
	}
	return keys
}

// systemGatewayResolveInterface returns the interface key for value, which may be the key or the name (LAN) of an
// interface gateways can use
func systemGatewayResolveInterface(api *system.SystemApi, value string) (string, error) {
	var interfaces, err = api.GatewayInterfaces()
	if err != nil {
		return "", err
	}
	var keys = make([]string, 0, len(interfaces))
	for _, iface := range interfaces {
		if strings.EqualFold(iface.Key, value) {
			return iface.Key, nil
		}
		keys = append(keys, iface.Key)
	}
	for _, iface := range interfaces {
		if strings.EqualFold(iface.Description, value) {
			return iface.Key, nil
		}
	}
	return "", fmt.Errorf("unknown interface %q, gateways can use: %s", value, strings.Join(keys, ", "))
}

// --- output

func systemGatewayFlags(gateway system.Gateway) string {
	var flags []string
	for _, flag := range []struct {
		set  bool
		name string
	}{
		{gateway.Default, "default"},
		{gateway.Upstream, "upstream"},
		{gateway.Dynamic, "dynamic"},
		{!gateway.IsConfigured(), "generated"},
		{gateway.ForceDown, "down"},
	} {
		if flag.set {
			flags = append(flags, flag.name)
		}
	}
	return strings.Join(flags, ",")
}

func systemGatewayYesNo(value bool) string {
	if value {
		return "yes"
	}
	return "no"
}

// systemGatewayThreshold renders a monitoring threshold, "" with the effective default when known
func systemGatewayThreshold(gateway system.Gateway, field string, value string) string {
	if value == "" && gateway.Current[field] != "" {
		return gateway.Current[field] + " (default)"
	}
	return value
}

func systemGatewayInterface(gateway system.Gateway) string {
	if gateway.InterfaceDescription == "" || strings.EqualFold(gateway.InterfaceDescription, gateway.Interface) {
		return gateway.Interface
	}
	return fmt.Sprintf("%s (%s)", gateway.Interface, gateway.InterfaceDescription)
}

func systemGatewayTruncate(text string, length int) string {
	var runes = []rune(text)
	if len(runes) <= length {
		return text
	}
	return string(runes[:length-3]) + "..."
}

// systemGatewayFields are the fields of show and print detail, named like the arguments of add and set
func systemGatewayFields(gateway system.Gateway) [][2]string {
	var configured = "yes"
	if !gateway.IsConfigured() {
		configured = "no, generated for a dynamic interface"
	}
	return [][2]string{
		{"uuid", gateway.Uuid},
		{"name", gateway.Name},
		{"disabled", systemGatewayYesNo(gateway.Disabled)},
		{"description", gateway.Description},
		{"interface", systemGatewayInterface(gateway)},
		{"device", gateway.Device},
		{"protocol", systemGatewayProtocolName(gateway.IpProtocol)},
		{"address", gateway.Address},
		{"dynamic", systemGatewayYesNo(gateway.Dynamic)},
		{"configured", configured},
		{"upstream", systemGatewayYesNo(gateway.Upstream)},
		{"default", systemGatewayYesNo(gateway.Default)},
		{"far-gateway", systemGatewayYesNo(gateway.FarGateway)},
		{"priority", gateway.Priority},
		{"weight", gateway.Weight},
		{"monitor-disabled", systemGatewayYesNo(gateway.MonitorDisable)},
		{"monitor", gateway.Monitor},
		{"monitor-no-route", systemGatewayYesNo(gateway.MonitorNoRoute)},
		{"kill-states", systemGatewayYesNo(gateway.MonitorKillStates)},
		{"kill-states-failback", systemGatewayYesNo(gateway.MonitorKillStatesPriority)},
		{"force-down", systemGatewayYesNo(gateway.ForceDown)},
		{"no-sync", systemGatewayYesNo(gateway.NoSync)},
		{"latency-low", systemGatewayThreshold(gateway, "latencylow", gateway.LatencyLow)},
		{"latency-high", systemGatewayThreshold(gateway, "latencyhigh", gateway.LatencyHigh)},
		{"loss-low", systemGatewayThreshold(gateway, "losslow", gateway.LossLow)},
		{"loss-high", systemGatewayThreshold(gateway, "losshigh", gateway.LossHigh)},
		{"interval", systemGatewayThreshold(gateway, "interval", gateway.Interval)},
		{"time-period", systemGatewayThreshold(gateway, "time_period", gateway.TimePeriod)},
		{"loss-interval", systemGatewayThreshold(gateway, "loss_interval", gateway.LossInterval)},
		{"data-length", systemGatewayThreshold(gateway, "data_length", gateway.DataLength)},
		{"status", gateway.Status},
		{"loss", gateway.Loss},
		{"delay", gateway.Delay},
		{"stddev", gateway.StdDev},
	}
}

// systemGatewayMatches tells whether any value of the raw row contains phrase (case-insensitive), like the search
// of OPNsense. search_gateway ignores searchPhrase on GET, so print filters itself
func systemGatewayMatches(gateway system.Gateway, phrase string) bool {
	if phrase == "" {
		return true
	}
	var row map[string]any
	if err := json.Unmarshal(gateway.Raw, &row); err != nil {
		return false
	}
	phrase = strings.ToLower(phrase)
	for _, value := range row {
		var text string
		switch v := value.(type) {
		case string:
			text = v
		case float64:
			text = strconv.FormatFloat(v, 'f', -1, 64)
		default:
			continue
		}
		if strings.Contains(strings.ToLower(text), phrase) {
			return true
		}
	}
	return false
}

func systemGatewayPrint(c *Context, args *Args) error {
	var api, err = systemGatewayApi(c)
	if err != nil {
		return err
	}
	var all, listErr = api.GatewayList()
	if listErr != nil {
		return listErr
	}
	var gateways []system.Gateway
	var uuids []string
	for _, gateway := range all {
		if systemGatewayMatches(gateway, args.String("search")) {
			gateways = append(gateways, gateway)
			uuids = append(uuids, gateway.Uuid)
		}
	}

	switch {
	case args.Bool("json"):
		for _, gateway := range gateways {
			c.Println(string(gateway.Raw))
		}
	case args.Bool("detail"):
		var items = make([][][2]string, len(gateways))
		for i, gateway := range gateways {
			items[i] = systemGatewayFields(gateway)
		}
		c.Details(items, uuids)
	default:
		var rows = make([][]string, len(gateways))
		for i, gateway := range gateways {
			rows[i] = []string{systemGatewayYesNo(gateway.Disabled), gateway.Name, gateway.Interface,
				systemGatewayProtocolName(gateway.IpProtocol), gateway.Address, gateway.Priority, systemGatewayFlags(gateway),
				gateway.Status, systemGatewayTruncate(gateway.Description, 40)}
		}
		c.Items([]string{"DISABLED", "NAME", "INTERFACE", "PROTOCOL", "ADDRESS", "PRIORITY", "FLAGS", "STATUS", "DESCRIPTION"}, rows, uuids)
	}
	return nil
}

func systemGatewayShow(c *Context, args *Args) error {
	var api, err = systemGatewayApi(c)
	if err != nil {
		return err
	}
	var gateway, selectErr = systemGatewaySelect(c, api, args.String("item"))
	if selectErr != nil {
		return selectErr
	}
	c.Fields(systemGatewayFields(gateway))
	return nil
}

// --- changes

// systemGatewayChanges returns the given field arguments as API fields, with all also the defaults of the
// arguments not given. The interface is resolved to its key
func systemGatewayChanges(api *system.SystemApi, args *Args, all bool) (system.GatewayFields, error) {
	var fields = system.GatewayFields{}
	for _, mapping := range systemGatewayFieldMap {
		if !all && !args.Has(mapping.arg) {
			continue
		}
		var value = args.String(mapping.arg)
		switch mapping.arg {
		case "protocol":
			value = systemGatewayProtocol(value)
		case "disabled", "upstream", "far-gateway", "monitor-disabled", "monitor-no-route", "kill-states",
			"kill-states-failback", "force-down", "no-sync":
			value = Flag(args.Bool(mapping.arg))
		case "interface":
			var key, err = systemGatewayResolveInterface(api, value)
			if err != nil {
				return nil, err
			}
			value = key
		}
		fields[mapping.field] = value
	}
	return fields, nil
}

func systemGatewayAdd(c *Context, args *Args) error {
	var api, err = systemGatewayApi(c)
	if err != nil {
		return err
	}
	var name = args.String("name")
	var gateways, listErr = api.GatewayList()
	if listErr != nil {
		return listErr
	}
	var existing *system.Gateway
	for i := range gateways {
		if strings.EqualFold(gateways[i].Name, name) {
			existing = &gateways[i]
			break
		}
	}
	if existing != nil && !args.Bool("replace") {
		return fmt.Errorf("gateway %s exists already (%s), change it with set or replace it with add ... replace", existing.Name, existing.Uuid)
	}

	var fields, changesErr = systemGatewayChanges(api, args, true)
	if changesErr != nil {
		return changesErr
	}
	fields["name"] = name

	if existing == nil {
		var uuid, createErr = api.GatewayCreate(fields)
		if createErr != nil {
			return createErr
		}
		c.Println(uuid)
		return nil
	}

	var uuid, updateErr = api.GatewayUpdate(existing.Uuid, fields)
	if updateErr != nil {
		return updateErr
	}
	if existing.IsConfigured() {
		c.Infof("replaced the existing gateway %s", existing.Name)
	} else {
		c.Infof("stored an override of the generated gateway %s", existing.Name)
	}
	c.Println(uuid)
	return nil
}

func systemGatewaySet(c *Context, args *Args) error {
	var given = false
	for _, mapping := range systemGatewayFieldMap {
		given = given || args.Has(mapping.arg)
	}
	if !given {
		return errors.New("set: nothing to change, give at least one field like address= or priority= (type \"set ?\" for help)")
	}

	var api, err = systemGatewayApi(c)
	if err != nil {
		return err
	}
	var gateway, selectErr = systemGatewaySelect(c, api, args.String("item"))
	if selectErr != nil {
		return selectErr
	}
	var fields, changesErr = systemGatewayChanges(api, args, false)
	if changesErr != nil {
		return changesErr
	}
	var uuid, updateErr = api.GatewayUpdate(gateway.Uuid, fields)
	if updateErr != nil {
		return updateErr
	}
	if !gateway.IsConfigured() {
		c.Infof("stored an override of the generated gateway %s, uuid %s", gateway.Name, uuid)
	}
	return nil
}

func systemGatewayRemove(c *Context, args *Args) error {
	var api, err = systemGatewayApi(c)
	if err != nil {
		return err
	}
	var gateway, selectErr = systemGatewaySelect(c, api, args.String("item"))
	if selectErr != nil {
		return selectErr
	}
	if !gateway.IsConfigured() {
		return fmt.Errorf("%s is generated by OPNsense for the dynamic interface %s and can not be removed, disable it instead",
			gateway.Name, gateway.Interface)
	}
	if err := api.GatewayRemove(gateway.Uuid); err != nil {
		return err
	}
	if gateway.Dynamic {
		c.Infof("removed the override, the gateway %s generated for the dynamic interface %s applies again", gateway.Name, gateway.Interface)
	}
	return nil
}

func systemGatewayEnabler(enabled bool) func(c *Context, args *Args) error {
	return func(c *Context, args *Args) error {
		var api, err = systemGatewayApi(c)
		if err != nil {
			return err
		}
		var gateway, selectErr = systemGatewaySelect(c, api, args.String("item"))
		if selectErr != nil {
			return selectErr
		}
		var changed, toggleErr = api.GatewaySetEnabled(gateway.Uuid, enabled)
		if toggleErr != nil {
			return toggleErr
		}
		switch {
		case !changed:
			c.Infof("gateway %s is already %s", gateway.Name, EnabledWord(enabled))
		case !gateway.IsConfigured():
			c.Infof("stored an override of the generated gateway %s", gateway.Name)
		}
		return nil
	}
}

func systemGatewayApply(c *Context, _ *Args) error {
	var api, err = systemGatewayApi(c)
	if err != nil {
		return err
	}
	return api.GatewayReconfigure()
}

// --- monitor

func systemGatewayMonitor(c *Context, args *Args) error {
	var api, err = systemGatewayApi(c)
	if err != nil {
		return err
	}
	var follow = !args.Bool("once")
	var asJSON = args.Bool("json")
	var refresh = systemActivityNewRefresher(c, follow && !asJSON)

	return systemActivityPoll(c, follow, args.Duration("interval"), func() error {
		var statuses, statusErr = systemActivityAwait(c, api.GatewayStatuses)
		if statusErr != nil {
			return statusErr
		}
		if asJSON {
			for _, status := range statuses {
				c.Println(string(status.Raw))
			}
			return nil
		}
		refresh()
		var rows = make([][]string, len(statuses))
		for i, status := range statuses {
			var state = status.StatusTranslated
			if state == "" {
				state = status.Status
			}
			rows[i] = []string{status.Name, status.Address, state, status.Loss, status.Delay, status.StdDev, status.Monitor}
		}
		c.Table([]string{"NAME", "ADDRESS", "STATUS", "LOSS", "DELAY", "STDDEV", "MONITOR"}, rows)
		return nil
	})
}
